  source: [['Where this comes from', 'Nguồn'], ['Business and software requirements, the change log and the code. The requirements mark their own pain points as inferred, so buyers and exporters still need to be interviewed.', 'Tài liệu nghiệp vụ, tài liệu phần mềm, nhật ký thay đổi và mã nguồn. Chính tài liệu ghi các điểm đau là suy luận, nên vẫn cần phỏng vấn bên mua và nhà xuất khẩu.']],
  users: [[['Guest', 'Khách'], ['Browses, sends a request for quotation, registers with the full form.', 'Xem, gửi yêu cầu báo giá, đăng ký bằng form đầy đủ.']], [['Buyer', 'Bên mua'], ['Posts import requests and looks for the verified badge.', 'Đăng yêu cầu nhập khẩu và tìm dấu xác thực.']], [['Seller', 'Bên bán'], ['Builds one capability profile and reuses it everywhere.', 'Lập một hồ sơ năng lực rồi dùng lại ở mọi nơi.']], [['VCCI staff', 'Cán bộ VCCI'], ['Approve organisations, products, events and translations.', 'Duyệt doanh nghiệp, sản phẩm, sự kiện và bản dịch.']]],
